using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _sut = null!;

    [TestInitialize]
    public void Setup() => _sut = new ShoppingCart();

    // ─── AddItem ────────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _sut.AddItem("SKU-1", 2, 9.99m);

        Assert.AreEqual(1, _sut.Items.Count);
        var item = _sut.Items["SKU-1"];
        Assert.AreEqual(2, item.Quantity);
        Assert.AreEqual(9.99m, item.Price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_MergesQuantity()
    {
        _sut.AddItem("SKU-1", 2, 5.00m);
        _sut.AddItem("SKU-1", 3, 5.00m);

        Assert.AreEqual(1, _sut.Items.Count);
        Assert.AreEqual(5, _sut.Items["SKU-1"].Quantity);
    }

    [TestMethod]
    public void AddItem_DifferentSkus_BothAppear()
    {
        _sut.AddItem("A", 1, 10m);
        _sut.AddItem("B", 1, 20m);

        Assert.AreEqual(2, _sut.Items.Count);
    }

    [TestMethod]
    [DataRow(null, DisplayName = "null SKU")]
    [DataRow("", DisplayName = "empty SKU")]
    [DataRow("   ", DisplayName = "whitespace SKU")]
    public void AddItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.AddItem(sku!, 1, 1m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "zero quantity")]
    [DataRow(-1, DisplayName = "negative quantity")]
    public void AddItem_InvalidQuantity_Throws(int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", quantity, 1m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", 1, -1m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Succeeds()
    {
        _sut.AddItem("FREE", 1, 0m);

        Assert.AreEqual(0m, _sut.Items["FREE"].Price);
    }

    // ─── RemoveItem ─────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _sut.AddItem("SKU-1", 1, 10m);
        _sut.RemoveItem("SKU-1");

        Assert.AreEqual(0, _sut.Items.Count);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFoundException()
    {
        Assert.ThrowsException<KeyNotFoundException>(() => _sut.RemoveItem("NOPE"));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "null SKU")]
    [DataRow("", DisplayName = "empty SKU")]
    public void RemoveItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.RemoveItem(sku!));
    }

    // ─── CalculateTotal ─────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _sut.AddItem("A", 2, 10.00m); // 20
        _sut.AddItem("B", 3, 5.50m);  // 16.50

        Assert.AreEqual(36.50m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemoval_ExcludesRemovedItem()
    {
        _sut.AddItem("A", 1, 100m);
        _sut.AddItem("B", 1, 50m);
        _sut.RemoveItem("A");

        Assert.AreEqual(50m, _sut.CalculateTotal());
    }

    // ─── ApplyCoupon ────────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 10, DisplayName = "SAVE10 → 10%")]
    [DataRow("SAVE20", 20, DisplayName = "SAVE20 → 20%")]
    [DataRow("HALF", 50, DisplayName = "HALF → 50%")]
    public void ApplyCoupon_ValidCode_SetsDiscount(string code, int expectedPercent)
    {
        _sut.ApplyCoupon(code);

        Assert.AreEqual((decimal)expectedPercent, _sut.DiscountPercent);
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive()
    {
        _sut.ApplyCoupon("save10");

        Assert.AreEqual(10m, _sut.DiscountPercent);
    }

    [TestMethod]
    public void ApplyCoupon_UnknownCode_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.ApplyCoupon("BOGUS"));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "null code")]
    [DataRow("", DisplayName = "empty code")]
    public void ApplyCoupon_InvalidCode_Throws(string? code)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.ApplyCoupon(code!));
    }

    // ─── Coupon + Total integration ─────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 90.00, DisplayName = "10% off 100")]
    [DataRow("SAVE20", 80.00, DisplayName = "20% off 100")]
    [DataRow("HALF", 50.00, DisplayName = "50% off 100")]
    public void CalculateTotal_WithCoupon_AppliesDiscount(string coupon, double expected)
    {
        _sut.AddItem("X", 10, 10.00m); // subtotal = 100
        _sut.ApplyCoupon(coupon);

        Assert.AreEqual((decimal)expected, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_NoCoupon_ReturnsFullPrice()
    {
        _sut.AddItem("X", 2, 25m);

        Assert.AreEqual(50m, _sut.CalculateTotal());
        Assert.AreEqual(0m, _sut.DiscountPercent);
    }

    [TestMethod]
    public void ApplyCoupon_ReplacedBySecondCoupon_UsesLatest()
    {
        _sut.AddItem("X", 1, 100m);
        _sut.ApplyCoupon("SAVE10");
        _sut.ApplyCoupon("HALF");

        Assert.AreEqual(50m, _sut.CalculateTotal());
    }
}

